mapper.select:
SELECT a.id, a.monitor_id, a.store_id, a.alert_date, a.alert_type, a.old_value, a.new_value, a.status, a.handler_id, a.handle_time, a.handle_note, a.create_time, a.update_time, m.platform, m.marketplace, m.item_id, m.title, m.monitor_type, s.name AS store_name, u.nickname AS handler_name FROM ecom_monitor_alert a JOIN ecom_monitor m ON m.id = a.monitor_id LEFT JOIN ecom_store s ON s.id = a.store_id LEFT JOIN sys_user u ON u.id = a.handler_id
a.status = #{q.status}
ORDER BY a.alert_date DESC, a.id DESC
